import sqlite3
from pathlib import Path


def crea_db(con):
    con.execute(
        "CREATE TABLE IF NOT EXISTS prove (provino TEXT PRIMARY KEY, materiale TEXT NOT NULL, "
        "data TEXT NOT NULL, A0 REAL NOT NULL, Fmax REAL NOT NULL, Rm REAL NOT NULL)"
    )


def importa_cartella(con, cartella):
    crea_db(con)
    nuovi, saltati, errori = 0, 0, []
    with con:
        for f in sorted(Path(cartella).glob("*.txt")):
            try:
                p = leggi_file(f.read_text(encoding="utf-8"))
            except ValueError as e:
                errori.append(f"{f.name}: {e}")
                continue
            cur = con.execute(
                "INSERT OR IGNORE INTO prove VALUES (?, ?, ?, ?, ?, ?)",
                (p["provino"], p["materiale"], p["data"].isoformat(), p["A0"], p["Fmax"], round(p["Fmax"] / p["A0"], 1)),
            )
            if cur.rowcount:
                nuovi += 1
            else:
                saltati += 1
    return nuovi, saltati, errori
